"""Actual engine/cameras. Adverse changes affect isolated test worlds only."""
import argparse,json,unittest,sys,os,tempfile
from pathlib import Path
from test_expedition_integration import ExpeditionIntegration
from test_continuity import RecordedResult
OUT=Path(os.environ.get('ICARUS_SPECIMEN_ARTIFACTS',str(Path(tempfile.gettempdir())/'icarus-specimens')));OUT.mkdir(parents=True,exist_ok=True)
class SpecimenIntegration(ExpeditionIntegration):
 def live(self,p):
  self.start_field(p)
  for _ in range(100):
   self.advance(p,10);s=self.snap(p)
   if any(c['occupant'] for c in s['unifiedWorld']['biologicalLife49']['enclosures'].values()):return s
  self.fail('A physically collected specimen did not reach containment')
 def test_bio_staging_retargets_actual_corridor_instead_of_stranding_last_room(self):
  p=self.page();self.configure(p,"""s.remoteCore.autonomyEnabled=false;s.frontier.enabled=false;for(const q of s.crew.filter(q=>['Engineer','Scientist'].includes(q.job))){q.room='C04';q.target='B05';q.route=['B05'];q.nav={destination:'B05',at:'H:C:1',steps:['V:B:1','H:B:1','R:B05'],index:0,progress:.8,wait:0};q.task='Walking to prior assignment';q.taskMinutes=60;q.energy=95;q.hunger=0;q.vitals.fatigue=0;q.maintenanceRoom=null;q.systemAssignment=null;q.researchAssignment=null;}""")
  self.deck(p,'missions','active');p.locator('.field-request').click();before=self.snap(p);m=before['missions']['asteroid'];self.assertIsNotNone(m);workers=[q for q in before['crew'] if q.get('expeditionId')==m['id']];self.assertEqual(len(workers),2);self.assertTrue(all(q['route']==['C04'] and q['nav']['at']=='H:C:1' for q in workers),'Retargeting must retain the actual corridor and require a physical route back')
  self.advance(p,120);after=self.snap(p);active=after['missions']['asteroid'];self.assertTrue(after['expeditionOperations']['history'] or active and active['ops44']['stage'] not in ['collect','stage'],'Physical staging remained blocked on stale navigation');self.assertEqual(after['resourceAudit'],[]);self.assertEqual(after['expeditionAudit'],[])
 def test_bio_actual_host_payload_counts_recovered_chassis(self):
  p=self.page();self.start_field(p);before=p.evaluate('__icarusSoak.fieldPayload()');self.change(p,"""const m=s.remoteCore.missions.asteroid;s.droneOperations.drones['DRONE-1']={id:'DRONE-1',stage:'carried',carrierMission:m.id,node:null,edge:null,battery:0,capacity:100,charged:0,used:0,condition:100,sensors:{optical:100,thermal:100,mineral:100,radiation:100,structural:100,environment:100,radio:100,light:100},map:{},clips:[],ring:[],pendingEvents:[],nextRecord:1,lastReport:null,source:'Explicit combined-payload regression fixture; no installed voyage modified',missions:0};""");after=p.evaluate('__icarusSoak.fieldPayload()');self.assertAlmostEqual(after['carried']-before['carried'],4);self.assertAlmostEqual(after['load']-before['load'],4);self.assertEqual(after['capacity'],before['capacity']);self.assertEqual(self.snap(p)['droneAudit'],[])
 def test_bio_natural_acquisition_camera_research_and_restart(self):
  p=self.page();s=self.live(p);bio=s['unifiedWorld']['biologicalLife49'];self.assertGreater(bio['stats']['collected'],0);self.assertEqual(s['biologyAudit'],[]);self.assertEqual(s['resourceAudit'],[]);self.assertTrue(s['unifiedWorld']['organisms']['XENO-INITIAL']['dormant']);view=p.evaluate('__icarusSoak.observation().rooms.find(r=>r.id==="B03")');self.assertTrue(view['specimens']);self.assertEqual(len(view['enclosures']),4);self.assertTrue(any(c.get('specimenId')==next(i['id'] for i in s['specimenCustody']['items'] if i.get('organismId49')) for c in s['director']['science']['cases']));
  # Explicit time advancement can outrun the one-second UI; await its current visible projection.
  self.deck(p,'ship','systems');p.wait_for_function('tick=>document.querySelector(".bio-status").textContent.endsWith("tick "+tick)&&document.querySelector(".bio-enclosures").textContent.includes("BIO49-")',arg=s['tick']);self.assertIn('BIO49-',p.locator('.specimen-ops').inner_text());p.locator('.bio-camera').click();p.wait_for_function('ICARUSObservationLive.camera.selected==="B03"');p.evaluate('ICARUSObservationLive.camera.draw(true)');p.locator('#observation-primary').screenshot(path=str(OUT/'living_containment.png'));p.screenshot(path=str(OUT/'bridge_containment.png'));before=self.snap(p);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),before);self.assertEqual(p.evaluate('__icarusSoak.observation().rooms.find(r=>r.id==="B03").specimens'),view['specimens']);(OUT/'natural_acquisition.json').write_text(json.dumps({'scope':'Isolated real browser campaign; explicit captain expedition dispatch, no organisms or findings injected','tick':s['tick'],'stats':bio['stats'],'view':view,'audits':{'biology':s['biologyAudit'],'resources':s['resourceAudit']},'save_reload_exact':True},indent=2))
 def test_bio_camera_power_loss_withholds_occupants_without_erasing_them(self):
  p=self.page();s=self.live(p);before=s['unifiedWorld']['biologicalLife49'];self.change(p,"s.shipSystems.zones.science.circuitIsolated=true;");self.advance(p,1);views=p.evaluate('__icarusSoak.observation().rooms.find(r=>r.id==="B03")');self.assertFalse(views['available']);self.assertEqual(views['specimens'],[]);self.assertEqual(views['enclosures'],[]);after=self.snap(p);self.assertEqual([c['occupant'] for c in after['unifiedWorld']['biologicalLife49']['enclosures'].values()],[c['occupant'] for c in before['enclosures'].values()]);self.assertEqual(after['unifiedWorld']['biologicalLife49']['stats']['escapes'],0)
 def test_bio_emergency_save_reload_and_real_week_boundary_keep_specimen_identity(self):
  p=self.page();s=self.live(p);ids=[o['id'] for o in s['unifiedWorld']['organisms'].values() if o.get('life49',{}).get('enclosure')];self.change(p,"s.shipSystems.zones.science.circuitIsolated=true;");self.advance(p,4);before=self.snap(p);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),before);p.evaluate("__icarusSoak.realStart(Date.parse('2026-11-08T23:59:00Z'),'UTC')");p.evaluate("__icarusSoak.realAdvance(Date.parse('2026-11-09T00:01:00Z'),60)");after=self.snap(p);self.assertGreater(after['episode'],before['episode']);self.assertEqual([o['id'] for o in after['unifiedWorld']['organisms'].values() if o.get('life49',{}).get('enclosure')],ids);self.assertEqual(after['biologyAudit'],[])
 def test_bio_genuine_enclosure_damage_can_escape_without_releasing_initial_xenomorph(self):
  p=self.page();self.live(p);self.change(p,"const o=Object.values(s.unifiedWorld.organisms).find(o=>o.life49?.enclosure);o.life49.family='grazer';const c=s.unifiedWorld.biologicalLife49.enclosures[o.life49.enclosure];c.integrity=0;c.latched=false;");self.advance(p,80);s=self.snap(p);self.assertGreater(s['unifiedWorld']['biologicalLife49']['stats']['escapes'],0);self.assertTrue(s['unifiedWorld']['organisms']['XENO-INITIAL']['dormant']);self.assertEqual(s['unifiedWorld']['military']['doors']['23'],'sealed');self.assertEqual(s['biologyAudit'],[]);self.assertTrue(any(r.get('data',{}).get('biology49') for r in s['chronicle']['records']));p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),s)
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--report',type=Path,required=True);args=ap.parse_args();names=[n for n in unittest.defaultTestLoader.getTestCaseNames(SpecimenIntegration) if n.startswith('test_bio_')];r=unittest.TextTestRunner(verbosity=2,resultclass=RecordedResult).run(unittest.TestSuite(SpecimenIntegration(n) for n in names));args.report.parent.mkdir(parents=True,exist_ok=True);args.report.write_text(json.dumps({'passed':r.wasSuccessful(),'tests_run':r.testsRun,'passed_cases':r.successes,'failures':[(str(t),d) for t,d in r.failures],'errors':[(str(t),d) for t,d in r.errors],'skipped':[(str(t),d) for t,d in r.skipped]},indent=2));raise SystemExit(not r.wasSuccessful())
